//! Work Management domain entities: Workspace, Area, Goal, Project, Task.
//!
//! Ownership and model per PRD §3.1/§4.2 and `data-architecture.md` §1: the
//! Work Management domain owns these records; cross-domain modules may only
//! touch them through published application contracts. All relationships are
//! workspace-consistent — composite (id, workspace_id) keys in the schema and
//! typed bindings here prevent cross-workspace references by construction.

use serde::{Deserialize, Serialize};

/// Opaque identifier newtype. Values are UUIDv7 text generated by the
/// application; callers must not infer ordering or authorization from them.
/// Internal macro: declare one opaque UUIDv7-text identifier newtype.
/// Shared by work_management and learning/knowledge entities.
macro_rules! opaque_id {
    ($name:ident, $doc:literal) => {
        #[doc = $doc]
        #[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
        pub struct $name(String);

        impl $name {
            /// Build from a validated UUIDv7 text value.
            pub fn new(
                value: impl Into<String>,
            ) -> Result<Self, crate::work_management::ParseError> {
                let s = value.into();
                if uuid::Uuid::parse_str(&s).is_err() {
                    return Err(crate::work_management::ParseError(s));
                }
                Ok(Self(s))
            }

            /// Generate a fresh UUIDv7 identifier.
            pub fn new_v7() -> Self {
                Self(uuid::Uuid::now_v7().to_string())
            }

            /// Borrow the raw text.
            pub fn as_str(&self) -> &str {
                &self.0
            }
        }
    };
}
pub(crate) use opaque_id;

opaque_id!(WorkspaceId, "Opaque workspace identifier (UUIDv7 text).");
opaque_id!(AreaId, "Opaque area identifier (UUIDv7 text).");
opaque_id!(GoalId, "Opaque goal identifier (UUIDv7 text).");
opaque_id!(ProjectId, "Opaque project identifier (UUIDv7 text).");
opaque_id!(TaskId, "Opaque task identifier (UUIDv7 text).");

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError(pub String);

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "invalid identifier: {}", self.0)
    }
}

impl std::error::Error for ParseError {}

/// Domain invariant violation for entity construction. Business invariants
/// live in the owning domain module (ADR-017); the persistence layer's CHECK
/// constraints mirror the same limits.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ValidationError {
    /// A required name or title was empty or whitespace-only after trimming.
    EmptyName,
    /// A name or title exceeded its domain limit (`max`) after trimming.
    NameTooLong { max: usize },
    /// Free-form notes exceeded their limit (`max`) after trimming.
    NotesTooLong { max: usize },
}

impl std::fmt::Display for ValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::EmptyName => write!(f, "name must not be empty"),
            Self::NameTooLong { max } => write!(f, "name exceeds {max} characters"),
            Self::NotesTooLong { max } => write!(f, "notes exceed {max} characters"),
        }
    }
}

impl std::error::Error for ValidationError {}

/// Trim and validate a required name/title against its schema-mirrored
/// limit. `chars().count()` mirrors SQLite `length()` for text values.
/// Public so application updates of existing records re-validate through
/// the same rule the constructors use.
pub fn validate_name(name: &str, max: usize) -> Result<String, ValidationError> {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        return Err(ValidationError::EmptyName);
    }
    if trimmed.chars().count() > max {
        return Err(ValidationError::NameTooLong { max });
    }
    Ok(trimmed.to_string())
}

/// Trim and validate optional free-form notes against their limit.
fn validate_notes(notes: Option<&str>, max: usize) -> Result<Option<String>, ValidationError> {
    match notes {
        None => Ok(None),
        Some(text) => {
            let trimmed = text.trim();
            if trimmed.chars().count() > max {
                return Err(ValidationError::NotesTooLong { max });
            }
            // Empty notes are stored as NULL, not as an empty string.
            Ok(if trimmed.is_empty() {
                None
            } else {
                Some(trimmed.to_string())
            })
        }
    }
}

/// Maximum notes length for tasks, mirrored by application-side validation.
pub const TASK_NOTES_MAX: usize = 10_000;

/// A workspace is the top-level tenancy boundary for the workbench.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Workspace {
    pub id: WorkspaceId,
    pub name: String,
}

impl Workspace {
    /// Construct a validated workspace: trims the name and enforces the
    /// 1..=120 character invariant mirrored by the database CHECK.
    pub fn new(id: WorkspaceId, name: &str) -> Result<Self, ValidationError> {
        Ok(Self {
            id,
            name: validate_name(name, 120)?,
        })
    }
}

/// An Area is a responsibility domain that is continuously maintained
/// (PRD §1); it groups goals and projects but owns no lifecycle of its own
/// beyond its record.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Area {
    pub id: AreaId,
    pub workspace_id: WorkspaceId,
    pub name: String,
    pub description: Option<String>,
}

impl Area {
    /// Construct a validated area (name 1..=120, mirrored by the CHECK).
    pub fn new(
        id: AreaId,
        workspace_id: WorkspaceId,
        name: &str,
        description: Option<&str>,
    ) -> Result<Self, ValidationError> {
        Ok(Self {
            id,
            workspace_id,
            name: validate_name(name, 120)?,
            description: description.map(str::to_string),
        })
    }
}

/// A Goal is a long- or medium-term outcome the user wants to reach; it may
/// belong to an Area of the same workspace.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Goal {
    pub id: GoalId,
    pub workspace_id: WorkspaceId,
    /// The Area this goal belongs to, when any. Same-workspace by type.
    pub area_id: Option<AreaId>,
    pub name: String,
    pub description: Option<String>,
}

impl Goal {
    /// Construct a validated goal (name 1..=200, mirrored by the CHECK).
    pub fn new(
        id: GoalId,
        workspace_id: WorkspaceId,
        area_id: Option<AreaId>,
        name: &str,
        description: Option<&str>,
    ) -> Result<Self, ValidationError> {
        Ok(Self {
            id,
            workspace_id,
            area_id,
            name: validate_name(name, 200)?,
            description: description.map(str::to_string),
        })
    }
}

/// Project lifecycle states (schema CHECK mirror). PRD §4.2 requires the
/// status to be recorded; the E2 slice records free transitions — stricter
/// transition rules, if ever needed, belong in the domain and would be
/// introduced with an explicit decision.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ProjectStatus {
    Active,
    Paused,
    Completed,
    Archived,
}

impl ProjectStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Active => "active",
            Self::Paused => "paused",
            Self::Completed => "completed",
            Self::Archived => "archived",
        }
    }

    pub fn parse(value: &str) -> Option<Self> {
        Some(match value {
            "active" => Self::Active,
            "paused" => Self::Paused,
            "completed" => Self::Completed,
            "archived" => Self::Archived,
            _ => return None,
        })
    }
}

impl std::fmt::Display for ProjectStatus {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// A project lives inside exactly one workspace and may link to a Goal
/// and/or an Area of that workspace (PRD §4.2).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Project {
    pub id: ProjectId,
    pub workspace_id: WorkspaceId,
    /// The Goal this project serves, when any. Same-workspace by type.
    pub goal_id: Option<GoalId>,
    /// The Area this project belongs to, when any. Same-workspace by type.
    pub area_id: Option<AreaId>,
    pub name: String,
    pub description: Option<String>,
    pub status: ProjectStatus,
}

impl Project {
    /// Construct a validated project (name 1..=200, mirrored by the CHECK).
    /// Links default to unbound and status to Active; assign the public
    /// fields to change them.
    pub fn new(
        id: ProjectId,
        workspace_id: WorkspaceId,
        name: &str,
    ) -> Result<Self, ValidationError> {
        Ok(Self {
            id,
            workspace_id,
            goal_id: None,
            area_id: None,
            name: validate_name(name, 200)?,
            description: None,
            status: ProjectStatus::Active,
        })
    }
}

/// Task lifecycle states (E2 Work Management slice). Transitions are
/// validated in the domain; the schema CHECK mirrors the value set.
///
/// ```text
/// todo ──► in_progress ──► done (terminal)
///   │            │         ▲
///   │            └──► todo ┘ (rework)
///   └─► cancelled (terminal) ◄── in_progress
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TaskStatus {
    Todo,
    InProgress,
    Done,
    Cancelled,
}

impl TaskStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Todo => "todo",
            Self::InProgress => "in_progress",
            Self::Done => "done",
            Self::Cancelled => "cancelled",
        }
    }

    /// Parse the schema's text representation.
    pub fn parse(value: &str) -> Option<Self> {
        Some(match value {
            "todo" => Self::Todo,
            "in_progress" => Self::InProgress,
            "done" => Self::Done,
            "cancelled" => Self::Cancelled,
            _ => return None,
        })
    }

    pub fn is_terminal(self) -> bool {
        matches!(self, Self::Done | Self::Cancelled)
    }

    /// Allowed transitions: work starts, may be reworked back to `todo`,
    /// completes, or is cancelled from any active state. Terminal states
    /// do not transition; corrections re-create a task or are represented
    /// by later records (mirrors the durable-operation rule).
    pub fn can_transition_to(self, to: Self) -> bool {
        use TaskStatus::*;
        matches!(
            (self, to),
            (Todo, InProgress)
                | (Todo, Cancelled)
                | (InProgress, Done)
                | (InProgress, Todo)
                | (InProgress, Cancelled)
        )
    }
}

impl std::fmt::Display for TaskStatus {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// A Task is a concrete, trackable work item; it may belong to a Project of
/// the same workspace or stand alone (PRD §4.2).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Task {
    pub id: TaskId,
    pub workspace_id: WorkspaceId,
    /// The project this task belongs to, when any. Same-workspace by type.
    pub project_id: Option<ProjectId>,
    pub title: String,
    pub notes: Option<String>,
    pub status: TaskStatus,
}

impl Task {
    /// Construct a validated task: title 1..=200, notes ≤
    /// [`TASK_NOTES_MAX`]; new tasks always start in [`TaskStatus::Todo`].
    pub fn new(
        id: TaskId,
        workspace_id: WorkspaceId,
        project_id: Option<ProjectId>,
        title: &str,
        notes: Option<&str>,
    ) -> Result<Self, ValidationError> {
        Ok(Self {
            id,
            workspace_id,
            project_id,
            title: validate_name(title, 200)?,
            notes: validate_notes(notes, TASK_NOTES_MAX)?,
            status: TaskStatus::Todo,
        })
    }
}

// ---------------------------------------------------------------------------
// Project retrospective with learning-product backflow (E6 第二批, Beta 0.5;
// PRD §3.8/§5.3: 学习结果可回流项目复盘). Work Management owns the
// retrospective; learning sessions are referenced by id (ADR-014
// discipline) — the application layer validates existence and linkage.
// ---------------------------------------------------------------------------

opaque_id!(
    RetrospectiveId,
    "Opaque project retrospective identifier (UUIDv7 text)."
);

/// A project retrospective record. Append-oriented: corrections are new
/// records (same discipline as assessments). `learning_session_refs` are
/// the learning products flowing back into the project's review.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProjectRetrospective {
    pub id: RetrospectiveId,
    pub workspace_id: WorkspaceId,
    pub project_id: ProjectId,
    /// What the project learned / what to carry forward (复盘结论).
    pub summary: String,
    /// Learning sessions flowing back (validated by the application layer).
    pub learning_session_refs: Vec<crate::learning::SessionId>,
}

impl ProjectRetrospective {
    pub const SUMMARY_MAX: usize = 2000;

    pub fn new(
        id: RetrospectiveId,
        workspace_id: WorkspaceId,
        project_id: ProjectId,
        summary: &str,
        learning_session_refs: Vec<crate::learning::SessionId>,
    ) -> Result<Self, ValidationError> {
        let trimmed = summary.trim();
        if trimmed.is_empty() {
            return Err(ValidationError::EmptyName);
        }
        if trimmed.chars().count() > Self::SUMMARY_MAX {
            return Err(ValidationError::NotesTooLong {
                max: Self::SUMMARY_MAX,
            });
        }
        Ok(Self {
            id,
            workspace_id,
            project_id,
            summary: trimmed.to_string(),
            learning_session_refs,
        })
    }
}

#[cfg(test)]
mod retrospective_tests {
    use super::*;

    #[test]
    fn retrospective_validates_summary() {
        assert!(
            ProjectRetrospective::new(
                RetrospectiveId::new_v7(),
                WorkspaceId::new_v7(),
                ProjectId::new_v7(),
                "  ",
                Vec::new()
            )
            .is_err()
        );
        let long = "x".repeat(2001);
        assert!(
            ProjectRetrospective::new(
                RetrospectiveId::new_v7(),
                WorkspaceId::new_v7(),
                ProjectId::new_v7(),
                &long,
                Vec::new()
            )
            .is_err()
        );
        let ok = ProjectRetrospective::new(
            RetrospectiveId::new_v7(),
            WorkspaceId::new_v7(),
            ProjectId::new_v7(),
            "帧聚合解析已落地，下一步补互操作测试",
            Vec::new(),
        )
        .expect("valid");
        assert_eq!(ok.learning_session_refs.len(), 0);
    }
}
